def find_path(graph, start, goal):
    # Initialize the stack for DFS and set the parent of the start node to None
    stack = [(start, [start])]
    visited = set()

    while stack:
        (vertex, path) = stack.pop()
        if vertex not in visited:
            visited.add(vertex)
            for neighbor in graph[vertex]:
                if neighbor == goal:
                    return path + [neighbor]
                else:
                    stack.append((neighbor, path + [neighbor]))
    return None

