def find_path(graph, start, goal):
    # Track the path with visited nodes
    path = []
    # Track the visited nodes
    visited = set()

    def search(node):
        if node == goal:
            # Return the path from start to goal
            return path
        if node in visited:
            return None
        visited.add(node)
        # Update the path with current node
        path.append(node)
        # Recursively search for the goal
        for neighbor in graph[node]:
            new_path = search(neighbor)
            if new_path:
                return path + new_path
        return None

    return search(start)
